/**
 * @method
 * @name scwin.tx_downloadFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_downloadFile = async function () {
    try { return await $c.data.downFile("/info/noticeDownload.do", "", ($c.util.getComponent("dma_downloadFileReq") ? $c.util.getComponent("dma_downloadFileReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goSearch = async function () {
    /* sdd-asis-lifecycle:begin goSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.JLDINF50000 || { elements: [] });
    $c.util.getComponent("dma_goSearchReq").set("pageIndex", "1");
    fm.action = "/info/notice.do?method=noticeList";
    await scwin.tx_goSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goSearch2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goSearch2 = async function () {
    /* sdd-asis-lifecycle:begin goSearch2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.JLDINF30000 || { elements: [] });
    fm.action = "/info/notice.do?method=noticeList";
    await scwin.tx_goSearch2();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goView
 * @author Inswave
 * @date 2026. 09. 29
 * @param id
 * @returns
 * @hidden N
*/
scwin.goView = async function (id) {
    /* sdd-asis-lifecycle:begin goView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.JLDINF30000 || { elements: [] });
    $c.util.getComponent('dma_goSearchReq').set('contnId', id);
    frm.action = "/info/notice.do?method=noticeView";
    await scwin.tx_goView();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.downloadFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param contn_id attach_file_no
 * @returns
 * @hidden N
*/
scwin.downloadFile = async function (contn_id, attach_file_no) {
    /* sdd-asis-lifecycle:begin downloadFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = (document.downloadForm || { elements: [] });
    obj.action = '/info/noticeDownload.do';
    $c.util.getComponent("dma_downloadFileReq").set("method", 'noticeDownload');
    $c.util.getComponent("dma_goSearchReq").set("contnId", contn_id);
    $c.util.getComponent('dma_downloadFileReq').set('attachFileNo', attach_file_no);
    await scwin.tx_downloadFile();
    /* sdd-asis-lifecycle:end */
};
